ids = ["LY-454","LY-455","LY-457","LY-458","LY-501","LY-502","LY-503","LY-504","LY-505","LY-506",
       "LY-507","LY-508","LY-509","LY-510","LY-511","LY-512","LY-513","LY-514","LY-515","LY-516"]
assert set(P.keys()) == set(ids), "案例集合与 B14 不符"
written = []
for cid in ids:
    rec = {"case_id": cid, "prediction_text": P[cid]["prediction_text"], "basis": P[cid]["basis"],
           "confidence": P[cid]["confidence"], "trigger": P[cid]["trigger"]}
    path = os.path.join(OUT, cid + ".json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(rec, f, ensure_ascii=False, indent=1)
    written.append(path)

# 自验：回读解析、字段齐备、case_id 与文件名对位
assert len(written) == len(ids) == 20
cm = ru = di = 0
for cid in ids:
    path = os.path.join(OUT, cid + ".json")
    with open(path, encoding="utf-8") as f:
        rec = json.load(f)
    assert rec["case_id"] == cid
    for k in ("case_id", "prediction_text", "basis", "confidence", "trigger"):
        assert k in rec, (cid, k)
    t = rec["trigger"]
    for k in ("changed_main", "reserve_used", "disputed", "reason"):
        assert k in t, (cid, k)
    assert isinstance(rec["confidence"], float) and 0.0 <= rec["confidence"] <= 1.0
    cm += t["changed_main"]; ru += t["reserve_used"]; di += t["disputed"]
print("WRITTEN", len(written))
print("TRIGGER changed_main=%d reserve_used=%d disputed=%d" % (cm, ru, di))
for cid in ids:
    print(cid, "OK", P[cid]["confidence"], P[cid]["trigger"]["changed_main"], P[cid]["trigger"]["reserve_used"], P[cid]["trigger"]["disputed"])
